  function zcApplySyncedTheme(index){
    if(!Number.isInteger(index)||index<0||index>=themes.length)return;
    zcMarkFrameDom();
    if(zcCurrentThemeIndex===index&&window.__zetaCozyTheme)return;
    zcCurrentThemeIndex=index;
    themes[index]();
    zcEnsureCompatStyle();
    window.__zetaRandomEightPickedIndex=index;
  }

  function zcSceneFrame(){
    return document.querySelector('iframe[title="scene"][src^="https://frame.pingpong.ai/"]');
  }
  function zcSendThemeToScene(index){
    if(!ZC_PARENT)return;
    const frame=zcSceneFrame();
    if(!frame?.contentWindow)return;
    try{frame.contentWindow.postMessage({type:ZC_SYNC,index},'https://frame.pingpong.ai');}catch(e){}
  }
  function zcOnThemeMessage(event){
    if(ZC_FRAME){
      if(!/^https:\/\/(?:www\.)?zeta-ai\.io$/.test(event.origin)||event.source!==window.parent)return;
      if(event.data?.type===ZC_SYNC&&Number.isInteger(event.data.index))zcApplySyncedTheme(event.data.index);
      return;
    }
    if(ZC_PARENT&&event.origin==='https://frame.pingpong.ai'&&event.data?.type===ZC_SYNC+'-ready'){
      const frame=zcSceneFrame();
      if(frame&&event.source===frame.contentWindow&&zcCurrentThemeIndex>=0)zcSendThemeToScene(zcCurrentThemeIndex);
    }
  }
  window.addEventListener('message',zcOnThemeMessage);

  if(ZC_FRAME){
    zcMarkFrameDom();
    if(document.documentElement){
      zcAdapterObserver=new MutationObserver(()=>zcMarkFrameDom());
      zcAdapterObserver.observe(document.documentElement,{childList:true,subtree:true});
    }
    try{window.parent.postMessage({type:ZC_SYNC+'-ready'},'*');}catch(e){}
  }
  // Pick once per page load. Refresh the page for another random theme.
  if (window.__zetaRandomEightLoaded) return;
  window.__zetaRandomEightLoaded = true;
